function buildState(overrides: Record<string, unknown> = {}) {
  const defaultJob = {
    id: JOB_ID,
    recordingId: RECORDING_ID,
    assessmentItemId: ITEM_ID,
    schoolId: SCHOOL_ID,
    targetText: "春眠不觉晓",
