    status: "PROCESSING",
    provider: "local",
    providerModel: null,
    result: null,
    confidence: null,
    processingMs: null,
    retryCount: 0,
    errorCode: null,
    createdAt: new Date("2026-01-01T00:00:00Z"),
    updatedAt: new Date("2026-01-01T00:00:00Z"),
  };
  const defaultItem = {
    id: ITEM_ID,
    recordingId: RECORDING_ID,
    maxScore: 4,
    scoredScore: null,
    questionVersionId: "version-0000-0000-0000-000000000001",
    session: { id: SESSION_ID, schoolId: SCHOOL_ID },
