      scoringSpec: {
        strategy: "SPEECH_READING",
        targetText: "春眠不觉晓",
        maxScore: 4,
      },
    },
  };
  const state: any = {
    job: {
      ...defaultJob,
      ...((overrides.job as Record<string, unknown> | undefined) ?? {}),
    },
    item: {
      ...defaultItem,
      ...((overrides.item as Record<string, unknown> | undefined) ?? {}),
    },
    recording: {
      id: RECORDING_ID,
      schoolId: SCHOOL_ID,
      ...((overrides.recording as Record<string, unknown> | undefined) ?? {}),
    },
